+/** Collects JSON frames through a pong, optionally sending work once the connection is announced. */
+export function framesThroughPong<T extends {type: string}>(client: WebSocket, onConnected?: () => void): Promise<T[]> {
+  const frames: T[] = [];
+  return new Promise<T[]>(resolve => {
+    client.on('message', raw => {
+      const frame = JSON.parse(String(raw)) as T;
+      frames.push(frame);
+      if (frame.type === 'connected') onConnected?.();
+      if (frame.type === 'pong') resolve(frames);
+    });
+  });
+}
